from ipaddress import IPv6Address, ip_address

from taf.sw.nadcm.interfaces.nadcm_v1 import NADCMv1
from taf.sw.nadcm.services.auth.authorization import Authorization


class NADCMVersionNotSupported(Exception):
    """ Raises when provided NOM version is not supported. """


class ConnectionDetails(object):
    def __init__(self, host, username, password, timeout):
        self.protocol = 'https://'
        self.host = host
        self.port = '443'
        self.username = username
        self.password = password
        self.timeout = timeout

        self.base_url = '{protocol}{host}:{port}'.format(protocol=self.protocol,
                                                         host=self.host,
                                                         port=self.port)

    @staticmethod
    def format_host_for_base_url(host):
        host = host.rstrip("]").lstrip("[")
        try:
            if isinstance(ip_address(host), IPv6Address):
                return '[{}]'.format(host)
            else:
                return host
        except (ValueError, TypeError):
            return host

class SupportedNADCMs(object):
    nadcm_v1 = NADCMv1


class NADCMProvider(object):
    @classmethod
    def create_nadcm(cls, host, username, password, nadcm_version='nadcm_v1', timeout=60):
        nadcm_type = getattr(SupportedNADCMs, nadcm_version, None)

        if not nadcm_type:
            exception_message = 'Version {} of nadcm is not supported'.format(nadcm_type)
            raise NADCMVersionNotSupported(exception_message)

        host = ConnectionDetails.format_host_for_base_url(host)
        token_details = Authorization.get_access_token_details(host, username, password)
        con_details = ConnectionDetails(host, username, password, timeout)
        nadcm = nadcm_type(con_details, token_details)

        return nadcm
